const upsertEmbeddingActive = `-- name: UpsertEmbeddingActive :one
INSERT INTO embedding_active (
  singleton,
  generation_id,
  flipped_at,
  flipped_reason
) VALUES (
  true,
  $1,
  now(),
  $2
)
ON CONFLICT (singleton) DO UPDATE
SET
  generation_id = EXCLUDED.generation_id,
  flipped_at = now(),
  flipped_reason = EXCLUDED.flipped_reason
RETURNING singleton, generation_id, flipped_at, flipped_reason
`

type UpsertEmbeddingActiveParams struct {
	GenerationID  int32
	FlippedReason *string
}

func (q *Queries) UpsertEmbeddingActive(ctx context.Context, arg UpsertEmbeddingActiveParams) (EmbeddingActive, error) {
	row := q.db.QueryRow(ctx, upsertEmbeddingActive, arg.GenerationID, arg.FlippedReason)
	var i EmbeddingActive
	err := row.Scan(
		&i.Singleton,
		&i.GenerationID,
		&i.FlippedAt,
		&i.FlippedReason,
	)
	return i, err
}
